import {difficultyChoices,difficultyLevels} from './difficulty-choices.js';
import {bindProgressKey} from './progress-key.js';
function levelSelect(key,label,values,current){return `<label>${label}<select data-filter="${key}" id="exam-${key}"><option value="">All</option>${values.map(v=>`<option ${current===v?'selected':''}>${v}</option>`).join('')}</select></label>`;}
import {enhanceFilters} from './filter-menu.js';
import {loadCatalog} from './data.js';
import {spotterPool,makeSpotter,answeredCount,remainingSeconds} from './spotter-logic.js';
const app=document.querySelector('#spotter-app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let advancedOpen=false;let difficulty=[...difficultyLevels],year='';
let selectedModels=[],selectedTopics=[],feedback='end',topicEffect='exclude',modelEffect='include',models=[];
const poolForRun=()=>spotterPool(catalog,region,{difficulty,year,topics:selectedTopics,topicEffect,models:selectedModels,modelEffect});
let catalog,region='',minutes=0,run=[],position=0,deadline=null,view='setup',confirmSubmit=false,expired=false;
const button=(text,action,extra='')=>`<button class="secondary" data-action="${action}" ${extra}>${text}</button>`;
function picture(image,reveal=false){const src=reveal&&image.answerSrc?image.answerSrc:image.quizSrc;const marker=image.quizMarker;return `<div class="marked-image"><img src="./${esc(src)}" alt="${reveal?esc(image.alt):esc(image.quizAlt||'Identify the marked structure.')}">${marker&&!(reveal&&image.answerSrc)?`<span class="image-marker" style="left:${marker.x*100}%;top:${marker.y*100}%" aria-hidden="true">?</span>`:''}</div>`;}
function setup(){view='setup';const pool=poolForRun();const regions=[...new Set(catalog.structures.flatMap(s=>s.regions))].sort();app.innerHTML=`<section class="spotter"><div class="eyebrow">Beyond the lab</div><h1>Mock spotter</h1><p class="muted">Difficulty is a suggested structure level. Year filters use direct learning-outcome links; unmapped structures remain available under All.</p><p class="intro">30 image questions. Choose question types, models, timing and answer mode.</p><div class="spotter-settings">${difficultyChoices(difficulty)}${levelSelect('year','Learning-outcome year',['Year 1','Year 2','Year not mapped'],year)}<label>Region<select data-filter="region" id="exam-region"><option value="">All regions</option>${regions.map(r=>`<option ${region===r?'selected':''}>${esc(r)}</option>`).join('')}</select></label><label>Time for a full mock<select data-filter="time" data-default-value="0" id="exam-time"><option value="0" ${!minutes?'selected':''}>Untimed</option><option value="30" ${minutes===30?'selected':''}>30 minutes</option><option value="45" ${minutes===45?'selected':''}>45 minutes</option></select></label><label>Show answers<select data-filter="feedback" data-default-value="end" id="exam-feedback"><option value="end" ${feedback==='end'?'selected':''}>At the end</option><option value="each" ${feedback==='each'?'selected':''}>After each question</option></select></label></div><details class="advanced-options exam-filters" ${advancedOpen?'open':''}><summary>Advanced options${selectedTopics.length||selectedModels.length?`<span>${selectedTopics.length} question types · ${selectedModels.length} models</span>`:''}</summary><section><h2>Question types</h2><p>Choose what you want to be asked. For example, exclude Origin and Insertion.</p><div class="tag-mode-row segments">${['include','exclude'].map(v=>`<button data-action="topic-effect" data-value="${v}" aria-pressed="${topicEffect===v}">${v==='include'?'Only selected types':'Exclude selected types'}</button>`).join('')}</div><div class="chips">${['Identification','Actions','Innervation','Function','Origin','Insertion','Blood supply','Sensory functions','Motor functions'].map(t=>`<button class="chip" data-action="topic" data-value="${esc(t)}" aria-pressed="${selectedTopics.includes(t)}">${esc(t)}</button>`).join('')}</div><p>${selectedTopics.length?`${topicEffect==='exclude'?'Excluded':'Included'}: ${selectedTopics.map(esc).join(', ')}`:'All question types included.'}</p><h2>Models</h2><p>Choose the models you have studied. This filters the photos used in your run.</p><div class="tag-mode-row segments">${['include','exclude'].map(v=>`<button data-action="model-effect" data-value="${v}" aria-pressed="${modelEffect===v}">${v==='include'?'Only selected models':'Exclude selected models'}</button>`).join('')}</div><input id="exam-model-search" type="search" placeholder="Find a model by name or code" aria-label="Find a model"><div class="chips exam-models">${models.map(m=>`<button class="chip" data-action="model-filter" data-value="${esc(m.id)}" aria-pressed="${selectedModels.includes(m.id)}">${esc(m.name)}</button>`).join('')}</div><p>${selectedModels.length?`${selectedModels.length} models ${modelEffect==='exclude'?'excluded':'included'}.`:'All models included.'}</p>${button('Reset filters','clear-filters')}</section></details><p class="exam-notice"><strong>${pool.length} structures ready.</strong> One question per structure. ${feedback==='each'?'Reveal the answer when ready.':'Answers appear after you end the exam.'}${pool.length<30?` Add ${30-pool.length} more to enable a full mock.`:''}</p><div class="spotter-bar">${button('Start 30-question mock','start',pool.length<30?'disabled':'')}${pool.length>0&&pool.length<30?button(`Practise ${pool.length} questions`,'practice'):''}</div>${!pool.length?'<p>Image questions will appear here as you add spotter-ready images. Knowledge revision is already available in the anatomy library.</p>':''}<a class="icon-link" href="./library.html"><span aria-hidden="true">▤</span> Anatomy library</a><p class="muted">Responses stay in this tab only. Refreshing or leaving the page ends your run.</p></section>`;enhanceFilters(app);}
function clockText(){const n=remainingSeconds(deadline);return n===null?'Untimed':`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')} remaining`;}
function paper(){const q=run[position];app.innerHTML=`<section class="spotter"><div class="spotter-bar"><strong>Question ${position+1} of ${run.length}</strong><time id="exam-clock">${clockText()}</time>${button('End exam','submit')}</div><progress max="${run.length}" value="${answeredCount(run)}" aria-label="Questions answered"></progress>${confirmSubmit?`<section class="exam-notice" role="alert"><p>${run.length-answeredCount(run)} unanswered. Submit now to finish and reveal all answers?</p>${button('Keep working','cancel-submit')} ${button('Submit and reveal answers','finish')}</section>`:''}<article class="spotter-paper">${picture(q.image)}<h2>${esc(q.question)}</h2><label for="exam-response">Your response</label><textarea id="exam-response" placeholder="Write your answer…">${esc(q.response)}</textarea>${feedback==='each'?`<div class="question-feedback">${q.revealed?`<h3>Answer</h3><p>${esc(q.answer)}</p>`:button('Reveal answer','reveal')}</div>`:''}<div class="spotter-bar">${button(q.flagged?'Flagged for review':'Flag for review','flag',`aria-pressed="${q.flagged}"`)}<span id="answered-summary">${answeredCount(run)} of ${run.length} answered</span></div></article><div class="spotter-bar">${button('← Previous','previous',position===0?'disabled':'')}${button(position===run.length-1?'Review & submit':'Next →',position===run.length-1?'submit':'next')}</div><nav class="question-jump" aria-label="Exam questions">${run.map((q,i)=>`<button data-action="jump" data-index="${i}" class="${q.response.trim()?'answered ':''}${q.flagged?'flagged':''}" aria-current="${i===position}" aria-label="Question ${i+1}${q.response.trim()?', answered':', unanswered'}${q.flagged?', flagged':''}">${i+1}</button>`).join('')}</nav><p class="muted">Blue: answered · Gold border: flagged.</p></section>`;}
function review(){view='review';confirmSubmit=false;app.innerHTML=`<section class="spotter"><div class="eyebrow">${expired?'Time is up':'Run complete'}</div><h1>Review your spotter</h1><p>${answeredCount(run)} of ${run.length} questions answered. Compare your wording with the key, then mark each response.</p><p id="mark-summary" role="status"></p>${button('New mock','new')}${run.map((q,i)=>`<article class="spotter-review"><h2>${i+1}. ${esc(q.question)}</h2><details><summary>View image · ${esc(q.name)}</summary>${picture(q.image,true)}${q.image.credit?`<p class="muted">${esc(q.image.credit)}${q.image.license?' · '+esc(q.image.license):''}</p>`:''}</details><h3>Your response</h3><p>${esc(q.response.trim()||'No response')}</p><h3>Answer</h3><p>${esc(q.answer)}</p><a class="icon-link" href="./library.html?structure=${encodeURIComponent(q.structureId)}" target="_blank" rel="noopener">Explore ${esc(q.name)}</a><div class="mark-controls">${button('Correct','correct',`data-index="${i}" aria-pressed="${q.mark===true}"`)}${button('Needs revision','incorrect',`data-index="${i}" aria-pressed="${q.mark===false}"`)}</div></article>`).join('')}<p class="muted">Self-marked practice only. Nothing is saved after this session.</p></section>`;markSummary();window.scrollTo(0,0);}
function markSummary(){const marked=run.filter(q=>q.mark!==null).length,correct=run.filter(q=>q.mark===true).length;document.querySelector('#mark-summary').textContent=`${correct} correct · ${marked} of ${run.length} reviewed${marked===run.length?` · ${Math.round(correct/run.length*100)}%`:''}`;}
app.addEventListener('toggle',e=>{if(e.target.matches('.advanced-options'))advancedOpen=e.target.open;},true);
app.addEventListener('input',e=>{if(e.target.id==='exam-model-search'){const q=e.target.value.toLowerCase();app.querySelectorAll('[data-action=model-filter]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));}if(e.target.id==='exam-response'){run[position].response=e.target.value;document.querySelector('#answered-summary').textContent=`${answeredCount(run)} of ${run.length} answered`;document.querySelector('progress').value=answeredCount(run);const b=app.querySelector(`[data-action="jump"][data-index="${position}"]`);b.classList.toggle('answered',!!e.target.value.trim());b.setAttribute('aria-label',`Question ${position+1}, ${e.target.value.trim()?'answered':'unanswered'}${run[position].flagged?', flagged':''}`);}});
app.addEventListener('change',e=>{if(e.target.dataset.difficulty){const level=e.target.dataset.difficulty;difficulty=e.target.checked?[...difficulty,level]:difficulty.filter(v=>v!==level);setup();app.querySelector(`[data-difficulty="${level}"]`)?.focus();}if(e.target.id==='exam-year'){year=e.target.value;setup();}if(e.target.id==='exam-region'){region=e.target.value;setup();}if(e.target.id==='exam-time')minutes=Number(e.target.value);if(e.target.id==='exam-feedback'){feedback=e.target.value;setup();}});
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='topic-effect'||a==='model-effect'){if(a==='topic-effect')topicEffect=b.dataset.value;else modelEffect=b.dataset.value;setup();return;}
 if(a==='model-filter'||a==='topic'){const list=a==='model-filter'?selectedModels:selectedTopics;const value=b.dataset.value;const i=list.indexOf(value);if(i<0)list.push(value);else list.splice(i,1);setup();return;}
 if(a==='clear-filters'){difficulty=[...difficultyLevels];year='';selectedModels=[];selectedTopics=[];topicEffect='exclude';modelEffect='include';setup();return;}
 if(a==='start'||a==='practice'){const pool=poolForRun();run=makeSpotter(pool,a==='start'?30:pool.length);position=0;expired=false;confirmSubmit=false;deadline=minutes?Date.now()+minutes*60000*(run.length/30):null;view='exam';paper();window.scrollTo(0,0);return;}
 if(a==='new'){run=[];deadline=null;setup();window.scrollTo(0,0);return;}
 if(a==='correct'||a==='incorrect'){run[Number(b.dataset.index)].mark=a==='correct';b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));markSummary();return;}
 if(view!=='exam')return;
 if(a==='reveal'&&feedback==='each'){run[position].revealed=true;paper();requestAnimationFrame(()=>app.querySelector('.question-feedback')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'}));return;}if(a==='finish'){review();return;}if(a==='submit')confirmSubmit=true;if(a==='cancel-submit')confirmSubmit=false;
 if(a==='flag')run[position].flagged=!run[position].flagged;
 if(a==='previous'&&position>0)position--;if(a==='next'&&position<run.length-1)position++;if(a==='jump')position=Number(b.dataset.index);paper();if(['previous','next','jump','submit'].includes(a))window.scrollTo(0,0);
});
app.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.hidden=true;const p=document.createElement('p');p.textContent='This image could not load. You can flag this question and continue.';p.setAttribute('role','status');e.target.parentElement.append(p);}},true);
setInterval(()=>{if(view!=='exam'||deadline===null)return;if(remainingSeconds(deadline)===0){expired=true;review();}else{const clock=document.querySelector('#exam-clock');if(clock)clock.textContent=clockText();}},500);
try{const response=await fetch('./data/models.json');if(!response.ok)throw Error('Models unavailable');models=await response.json();catalog=await loadCatalog();setup();}catch{app.innerHTML='<section class="spotter"><h1>The mock could not load</h1><p>Refresh the page to try again.</p></section>';}

bindProgressKey(()=>view==='exam',()=>{if(confirmSubmit)return;const action=feedback==='each'&&!run[position].revealed?'reveal':position===run.length-1?'submit':'next';app.querySelector(`[data-action="${action}"]`)?.click();});
